-- 세트 122: k8s 스토리지 개념: PV, PVC, StorageClass, 접근 모드
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (122, 1, 'PV 와 PVC 의 역할', 'k8s 의 저장소는 두 가지로 나눠 부릅니다. 실제 저장 공간을 뜻하는 것이 `PV`, 사용자가 "이만큼 주세요"라고 내는 것이 `PVC` 입니다. 빈칸에 알맞은 설명을 고르세요.', '창고와 창고 사용 신청서를 떠올려 보세요.', NULL, NULL, '[]', 'fill', '["실제 저장 공간", "요청서", "스케줄러", "이미지"]', NULL, 'Pod 는 PV 를 직접 쓰지 않고 **PVC 를 통해** 씁니다. 사용자는 "5Gi, 읽고 쓰기" 같은 요청(PVC)만 내고, 클러스터가 알맞은 PV 를 연결해 줍니다. 덕분에 앱 정의가 저장소 종류와 분리돼요.', '[0, 1]', 'PV: 클러스터에 있는 {0}
PVC: 그 공간을 달라는 {1}', NULL, NULL),
  (122, 2, 'waiting for first consumer', 'PVC 가 `Pending` 이고 이벤트에 `waiting for first consumer to be created before binding` 이 보입니다. 해석으로 알맞은 것은 무엇일까요?', 'StorageClass 의 binding 모드가 WaitForFirstConsumer 일 때 나오는 메시지예요.', NULL, NULL, '[]', 'choice', '["스토리지 서버가 고장 났다", "정상이다. 이 PVC 를 쓰는 Pod 가 만들어지고 노드가 정해질 때 비로소 볼륨이 만들어져 바인딩된다", "PVC 이름이 잘못됐다", "노드의 디스크가 가득 찼다"]', 1, 'WaitForFirstConsumer 는 Pod 가 배치될 노드를 보고 그 근처에 볼륨을 만들려는 방식입니다. Pod 를 만들면 곧 `Bound` 가 돼요. Pod 를 만들었는데도 계속 Pending 이면 그때 다른 원인을 찾습니다.', NULL, NULL, NULL, NULL),
  (122, 3, 'no persistent volumes available', 'PVC 이벤트에 `no persistent volumes available for this claim and no storage class is set` 가 반복됩니다. 가장 알맞은 해석과 조치는 무엇일까요?', '볼륨을 만들어 줄 StorageClass 가 정해졌는지 보세요.', NULL, NULL, '[]', 'choice', '["Pod 의 이미지가 틀렸다", "kubectl 버전이 오래됐다", "네임스페이스를 삭제한다", "PVC 에 storageClassName 이 없고 기본(default) StorageClass 도 없어, 맞는 PV 도 만들 곳도 없다. 클러스터에 있는 StorageClass 를 확인해 PVC 에 지정하거나 기본 클래스를 정한다"]', 3, '`kubectl get storageclass` 로 사용할 수 있는 클래스와 `(default)` 표시를 확인하세요. 없는 클래스 이름을 PVC 에 적었을 때도 비슷하게 Pending 이 됩니다. 이름 오타를 먼저 확인해요.', NULL, NULL, NULL, NULL),
  (122, 4, '접근 모드 읽기', 'PVC 의 `accessModes` 는 볼륨을 **몇 개의 노드가 동시에** 읽고 쓸 수 있는지를 정합니다. 빈칸을 채우세요.', 'Once 는 한 번이 아니라 "하나의 노드"를 뜻해요. Many 는 여러 개예요.', NULL, NULL, '[]', 'fill', '["한 개의", "여러 개의", "모든", "두 개의"]', NULL, '대부분의 블록 스토리지는 RWO 만 지원합니다. RWO 볼륨을 쓰는 Pod 를 여러 노드에 걸쳐 복제하면 다른 노드의 Pod 가 `Multi-Attach error` 로 ContainerCreating 에 멈춰요. 여러 노드가 같이 쓰려면 NFS 같은 RWX 를 지원하는 스토리지가 필요합니다.', '[0, 1]', 'ReadWriteOnce(RWO): {0} 노드에서 읽기·쓰기
ReadWriteMany(RWX): {1} 노드에서 읽기·쓰기', NULL, NULL),
  (122, 5, 'PVC 를 지웠더니 데이터가 사라졌어요', '동적 프로비저닝으로 만든 PVC 를 실수로 지웠더니 그 안의 데이터도 함께 사라졌습니다. 앞으로 중요한 데이터는 어떻게 보호하는 것이 좋을까요?', '볼륨을 반납할 때의 정책(reclaimPolicy)을 보세요.', NULL, NULL, '[]', 'choice', '["StorageClass(또는 PV)의 `reclaimPolicy` 를 `Retain` 으로 해 PVC 가 지워져도 PV 와 데이터를 남기고, 별도 백업도 둔다", "`reclaimPolicy: Delete` 로 바꾼다", "PVC 를 만들지 않고 컨테이너 안에 저장한다", "Pod 를 자주 재시작한다"]', 0, '동적 프로비저닝의 기본 정책은 보통 `Delete` 라서 PVC 를 지우면 PV 와 실제 볼륨도 지워집니다. `Retain` 은 데이터를 남기지만 사람이 정리해 줘야 해요. 어떤 경우에도 백업은 별도로 필요합니다.', NULL, NULL, NULL, NULL),
  (122, 6, '동적 프로비저닝 흐름', 'PVC 를 만들었더니 볼륨이 자동으로 생기고 Pod 가 쓰게 됩니다. 일어나는 순서에 맞게 놓아 보세요.', '요청 → 자동 생성 → 연결 → 사용 순이에요.', NULL, NULL, '[]', 'order', '["사용자가 storageClassName 을 가진 PVC 를 만든다", "StorageClass 의 프로비저너가 알맞은 PV(실제 볼륨)를 자동으로 만든다", "PV 가 PVC 에 바인딩되어 PVC 가 `Bound` 가 된다", "Pod 가 PVC 를 볼륨으로 마운트해 시작한다", "컨테이너가 마운트 경로에 읽고 쓴다"]', NULL, '운영자가 PV 를 미리 만들어 둘 필요 없이 PVC 만으로 저장소가 생기는 것이 동적 프로비저닝입니다. `kubectl get pvc` 가 `Bound` 인지 확인한 뒤 Pod 를 확인하세요.', '[0, 1, 2, 3, 4]', NULL, NULL, NULL),
  (122, 7, '임시 캐시는 어디에 둘까', '앱이 계산 중간 결과를 임시 파일로 쓰고, **Pod 가 사라지면 같이 사라져도 괜찮습니다.** 가장 알맞은 볼륨은 무엇일까요?', 'Pod 와 수명을 같이하는 볼륨이에요. 노드의 특정 폴더를 직접 쓰는 방식은 아니에요.', NULL, NULL, '[]', 'choice', '["`hostPath` 로 노드의 / 를 마운트한다", "`ReadWriteMany` PVC 를 새로 만든다", "`emptyDir` (Pod 가 사라질 때 함께 삭제되는 임시 볼륨)", "컨테이너 이미지에 파일을 넣는다"]', 2, '`emptyDir` 은 Pod 와 수명이 같은 임시 공간이라 캐시·임시 파일에 알맞습니다. 영구 보관이 필요하면 PVC 를 쓰세요. `hostPath` 는 노드 파일 시스템에 직접 닿아 노드 의존과 보안 위험이 있어 운영에서는 피하고, 이 연습 환경도 막습니다.', NULL, NULL, NULL, NULL),
  (122, 8, 'PVC 를 Pod 에 마운트하는 YAML', 'PVC `data-pvc` 를 Pod 의 `/var/lib/app` 경로에 마운트하는 YAML 입니다. 두 곳의 빈칸을 채우세요.', '볼륨 정의에서는 PVC 의 이름을, 컨테이너에서는 안쪽 경로를 적어요.', NULL, NULL, '[]', 'fill', '["data-pvc", "/var/lib/app", "ReadWriteOnce", "5Gi"]', NULL, '`volumes` 에서 PVC 를 가리키고(`claimName`), `volumeMounts` 가 같은 `name`(`data`)으로 컨테이너 안 경로에 붙입니다. 두 곳의 `name` 이 다르면 Pod 가 만들어지지 않아요.', '[0, 1]', 'volumes:
- name: data
  persistentVolumeClaim:
    claimName: {0}
containers:
- name: app
  image: nginx
  volumeMounts:
  - name: data
    mountPath: {1}', NULL, NULL),
  (122, 9, 'PVC 용량 늘리기', 'PVC 를 `5Gi` 에서 `10Gi` 로 고쳐 적용하자 `only dynamically provisioned pvc can be resized and the storageclass that provisions the pvc must support resize` 오류가 납니다. 알맞은 조치는 무엇일까요?', '크기 확장은 StorageClass 가 허용해야 해요.', NULL, NULL, '[]', 'choice', '["PVC 를 줄여서 3Gi 로 바꾼다", "StorageClass 에 `allowVolumeExpansion: true` 가 있어야 PVC 의 요청 용량을 늘릴 수 있다. 설정을 확인·변경한 뒤 다시 적용한다 (줄이는 것은 지원하지 않는다)", "Pod 를 지우면 자동으로 늘어난다", "노드를 재부팅한다"]', 1, '볼륨 확장은 스토리지 종류와 StorageClass 설정에 달려 있습니다. 지원하더라도 **늘리기만** 가능하고, 파일 시스템 확장은 Pod 재시작이 필요할 수 있어요.', NULL, NULL, NULL, NULL),
  (122, 10, 'StorageClass 설정 읽기', 'StorageClass 에서 ① PVC 용량을 **늘릴 수 있게** 허용하고, ② PVC 를 지워도 데이터를 **남기도록** 하는 설정입니다. 빈칸을 채우세요.', '확장은 true, 남기기는 Retain 입니다.', NULL, NULL, '[]', 'fill', '["true", "Retain", "false", "Delete"]', NULL, '`allowVolumeExpansion` 은 PVC 크기 확장 허용 여부, `reclaimPolicy` 는 PVC 삭제 후 PV 처리(`Delete`/`Retain`)입니다. 중요한 데이터라면 Retain 을 고려하세요.', '[0, 1]', 'allowVolumeExpansion: {0}
reclaimPolicy: {1}', NULL, NULL);
